package com.gatecraft.game;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import java.util.Random;

final class MetalFighterV5View extends BaseArcadeView {
  private final ArcadeFx fx=new ArcadeFx();private final Random rnd=new Random(7301L);
  private float x=205,ex=748,vx,evx,y,ey,vy,evy,ai,atk,eAtk,specialCd,hitFlash,shake,roundClock=65,comboTimer,special=35,hitStop,intro=1.6f,koTimer,enemyBlock;
  private int hp=100,ehp=100,score,round=1,wins,losses,combo,pAttack,eAttack,facing=1,eFacing=-1,matchRound=1;
  private boolean left,right,block,punch,kick,arc,jump,jumpLatch,ground=true,eGround=true;
  private final RectF bL=new RectF(18,432,110,524),bR=new RectF(116,432,208,524),bJ=new RectF(214,432,316,524),bP=new RectF(574,426,666,524),bK=new RectF(671,426,763,524),bB=new RectF(768,426,860,524),bA=new RectF(865,420,958,524);
  MetalFighterV5View(Context c,GateCraftGame owner){super(c,owner);}
  @Override public int score(){return score;}@Override public int level(){return round;}@Override public int lives(){return Math.max(1,2-losses);}@Override public void shutdown(){super.shutdown();fx.clear();}
  @Override public void restart(){x=205;ex=748;y=ey=0;vy=evy=0;hp=ehp=100;vx=evx=0;specialCd=hitFlash=shake=atk=eAtk=hitStop=koTimer=0;left=right=block=punch=kick=arc=jump=false;ground=eGround=true;roundClock=65;combo=0;comboTimer=0;special=Math.max(20,special);intro=1.55f;enemyBlock=0;invalidate();}
  @Override void updateGame(float dt){fx.update(dt);if(hitStop>0){hitStop=Math.max(0,hitStop-dt);return;}intro=Math.max(0,intro-dt);koTimer=Math.max(0,koTimer-dt);specialCd=Math.max(0,specialCd-dt);hitFlash=Math.max(0,hitFlash-dt);shake=Math.max(0,shake-dt);atk=Math.max(0,atk-dt);eAtk=Math.max(0,eAtk-dt);comboTimer=Math.max(0,comboTimer-dt);enemyBlock=Math.max(0,enemyBlock-dt);if(comboTimer<=0)combo=0;if(intro<=0&&koTimer<=0)roundClock=Math.max(0,roundClock-dt);special=Math.min(100,special+dt*4.5f);float sp=315;if(intro<=0&&koTimer<=0){if(left)vx=-sp;else if(right)vx=sp;else vx*=Math.pow(.0008,dt);if(jump&&!jumpLatch&&ground){vy=-575;ground=false;jumpLatch=true;fx.dust(x,385,8,Color.rgb(92,88,82));}if(!jump)jumpLatch=false;}else vx*=.7f;if(!ground){vy+=1360*dt;y+=vy*dt;if(y>=0){y=0;vy=0;ground=true;fx.dust(x,388,8,Color.rgb(98,93,84));}}x+=vx*dt;x=Math.max(58,Math.min(902,x));facing=x<=ex?1:-1;eFacing=-facing;if(intro<=0&&koTimer<=0)updateAI(dt);if(!eGround){evy+=1360*dt;ey+=evy*dt;if(ey>=0){ey=0;evy=0;eGround=true;}}ex+=evx*dt;ex=Math.max(58,Math.min(902,ex));evx*=Math.pow(.05,dt);separate();if(punch){punch=false;strike(10,104,1,.22f);}if(kick){kick=false;int bonus=combo>0?5:0;strike(16+bonus,130,2,.32f);}if(arc){arc=false;if(specialCd<=0&&special>=50){special-=50;specialCd=2.0f;strike(29,250,3,.44f);fx.sparks(x+facing*82,318+y,30,Color.rgb(100,202,255));}}if(roundClock<=0&&koTimer<=0){if(hp>=ehp)ehp=0;else hp=0;}if(ehp<=0&&koTimer<=0)finishRound(true);else if(hp<=0&&koTimer<=0)finishRound(false);}
  private void updateAI(float dt){ai-=dt;if(ai>0)return;ai=.13f+rnd.nextFloat()*.22f;float d=x-ex,ad=Math.abs(d);if(ad>170){evx=(d>0?1:-1)*(180+rnd.nextFloat()*90);enemyBlock=0;}else{evx*=.25f;float r=rnd.nextFloat();if(r<.20f)enemyBlock=.35f+rnd.nextFloat()*.45f;else if(r<.60f)enemyStrike(rnd.nextFloat()<.30f?2:1);else if(r<.72f&&eGround){evy=-510;eGround=false;}else if(r<.86f)evx=-eFacing*170;}}
  private void separate(){if(Math.abs(x-ex)<76&&Math.abs(y-ey)<65){float mid=(x+ex)/2;if(x<ex){x=Math.min(x,mid-39);ex=Math.max(ex,mid+39);}else{x=Math.max(x,mid+39);ex=Math.min(ex,mid-39);}}}
  private void strike(int dmg,float range,int kind,float duration){if(atk>0||intro>0||koTimer>0)return;pAttack=kind;atk=duration;if(Math.abs(x-ex)<=range&&Math.abs(y-ey)<84){int dealt=dmg+(combo>=2?4:0);if(enemyBlock>0){dealt=Math.max(3,dealt/3);special=Math.min(100,special+3);fx.sparks(ex-facing*26,318+ey,8,Color.rgb(190,210,230));}ehp-=dealt;ex+=facing*(kind==2?32:kind==3?44:20);hitFlash=.11f;shake=kind==3?.22f:.10f;hitStop=kind==3?.055f:.025f;combo++;comboTimer=.92f;special=Math.min(100,special+10);score+=dealt*(5+combo);owner.reportScore(score);fx.sparks(ex-facing*22,316+ey,kind==3?28:12,kind==3?Color.rgb(105,205,255):Color.rgb(255,192,70));}}
  private void enemyStrike(int kind){if(eAtk>0||intro>0||koTimer>0)return;eAttack=kind;eAtk=kind==2?.36f:.26f;if(Math.abs(x-ex)<(kind==2?130:105)&&Math.abs(y-ey)<84){int d=kind==2?18:12;if(block){d=4;special=Math.min(100,special+6);fx.sparks(x-facing*28,320+y,9,Color.rgb(190,210,230));}hp-=d;x-=facing*(block?6:20);hitFlash=.10f;shake=.09f;hitStop=.02f;combo=0;fx.sparks(x+facing*22,317+y,10,Color.rgb(255,145,55));}}
  private void finishRound(boolean playerWin){koTimer=1.15f;if(playerWin){wins++;score+=700+Math.max(0,(int)roundClock)*8;fx.sparks(ex,280,42,Color.rgb(255,218,75));}else{losses++;score=Math.max(0,score-180);fx.sparks(x,280,32,Color.rgb(231,78,56));}owner.reportScore(score);if(wins>=2||losses>=2){if(wins>=2){score+=1600;owner.reportGameComplete(score);round++;}else owner.reportGameOver(score);wins=losses=0;matchRound=1;resetLater();}else{matchRound++;resetLater();}}
  private void resetLater(){postDelayed(new Runnable(){@Override public void run(){restart();}},1150L);}
  @Override void drawGame(Canvas c){float sh=shake>0?(float)Math.sin(System.currentTimeMillis()*.08)*8:0;c.save();c.translate(sh,0);drawArena(c);fighter(c,x,389+y,false,facing,pAttack,atk,block);fighter(c,ex,389+ey,true,eFacing,eAttack,eAtk,enemyBlock>0);fx.draw(c,p);if(hitFlash>0)fill(c,Color.argb(58,255,235,175),0,74,960,410);c.restore();drawHud(c);if(intro>0){text(c,"ROUND "+matchRound,480,185,35,Color.rgb(255,219,80),Paint.Align.CENTER,true);if(intro<.72f)text(c,"FIGHT!",480,240,52,Color.WHITE,Paint.Align.CENTER,true);}if(koTimer>0)text(c,ehp<=0?"K.O.!":"DOWN!",480,210,56,ehp<=0?Color.rgb(255,218,75):Color.rgb(236,76,58),Paint.Align.CENTER,true);arcadeButton(c,bL,"◀",Color.rgb(45,99,158),left);arcadeButton(c,bR,"▶",Color.rgb(45,99,158),right);arcadeButton(c,bJ,"▲",Color.rgb(45,99,158),jump);arcadeButton(c,bP,t("ÜT","HIT","HIEB","GOLPE","COUP","拳","COLPO","SOCO","CIOS","SLAG","LOV","УДАР"),Color.rgb(169,58,43),touched(bP));arcadeButton(c,bK,t("RÚG","KICK","TRITT","PATADA","PIED","踢","CALCIO","CHUTE","KOP","TRAP","PICIOR","ПИНОК"),Color.rgb(178,91,35),touched(bK));arcadeButton(c,bB,t("VÉD","BLOCK","BLOCK","BLOQ","BLOC","防御","PARA","DEF","BLOK","BLOK","BLOC","БЛОК"),Color.rgb(54,101,139),block);arcadeButton(c,bA,(special>=50&&specialCd<=0)?t("ÍV","ARC","LICHT","ARCO","ARC","电弧","ARCO","ARCO","ŁUK","BOOG","ARC","ДУГА"):"…",Color.rgb(119,65,165),touched(bA));}
  private void drawArena(Canvas c){int theme=(round-1)%3;int base=theme==0?Color.rgb(76,42,91):theme==1?Color.rgb(32,72,91):Color.rgb(108,54,29);fill(c,shade(base,-52),0,0,960,540);fill(c,base,0,74,960,238);for(int yy=82;yy<238;yy+=18)fill(c,(yy/18)%2==0?shade(base,12):shade(base,-8),0,yy,960,yy+8);for(int bx=-30;bx<1000;bx+=145){fill(c,Color.rgb(39,34,37),bx,190,bx+76,392);fill(c,Color.rgb(102,70,43),bx+8,205,bx+19,392);fill(c,Color.rgb(13,15,19),bx+29,246,bx+64,392);for(int yy=260;yy<370;yy+=31)fill(c,Color.rgb(205,128,42),bx+37,yy,bx+52,yy+8);}for(int i=0;i<12;i++){float cx=30+i*80,cy=226+(i%2)*8;fill(c,Color.rgb(18,18,22),cx,cy,cx+34,cy+50);fill(c,i%3==0?Color.rgb(181,66,47):i%3==1?Color.rgb(50,105,155):Color.rgb(180,135,48),cx+6,cy+6,cx+28,cy+22);}fill(c,Color.rgb(65,37,30),427,284,540,390);fill(c,Color.rgb(232,84,29),446,305,521,365);fill(c,Color.rgb(255,199,57),459,315,508,351);for(int i=0;i<17;i++){float sx=475+(i%6)*12,sy=297-(i*19%66)+(float)Math.sin(i+System.currentTimeMillis()*.01)*4;fill(c,i%2==0?Color.rgb(255,216,73):Color.rgb(239,104,35),sx,sy,sx+3,sy+6);}fill(c,Color.rgb(42,50,58),0,358,960,540);for(int yy=360;yy<540;yy+=23)line(c,Color.rgb(25,31,37),2,0,yy,960,yy);for(int bx=-120;bx<1080;bx+=56)line(c,Color.rgb(67,77,84),2,bx,358,bx+155,540);line(c,Color.rgb(182,135,49),4,0,394,960,394);}
  private void drawHud(Canvas c){fill(c,Color.rgb(7,7,11),0,0,960,77);text(c,"METAL FIGHTER '98",480,30,27,Color.rgb(248,211,80),Paint.Align.CENTER,true);text(c,t("LAKATOS SZAKI","METALWORKER","METALLBAUER","HERRERO","MÉTALLIER","金属工","FABBRO","SERRALHEIRO","ŚLUSARZ","METAALBEWERKER","LĂCĂTUȘ","СЛЕСАРЬ"),18,61,13,Color.WHITE,Paint.Align.LEFT,true);text(c,t("KÓKLER KONTÁR","HACK RIVAL","PFUSCHER","CHAPUCERO","BRICOLEUR","劣质工","PASTICCIONE","GAMBIARRA","PARTACZ","BEUNHAAS","CÂRPACI","ХАЛТУРЩИК"),942,61,13,Color.WHITE,Paint.Align.RIGHT,true);bar(c,18,9,hp,Color.rgb(57,194,75),false);bar(c,662,9,ehp,Color.rgb(211,59,46),true);text(c,"R"+matchRound+"  "+Math.max(0,(int)roundClock)+"  "+wins+"-"+losses,480,60,18,Color.WHITE,Paint.Align.CENTER,true);fill(c,Color.rgb(31,30,37),345,11,615,19);fill(c,Color.rgb(112,65,164),347,13,347+266*special/100f,17);text(c,"ARC "+(int)special+"%",480,18,10,Color.rgb(214,190,255),Paint.Align.CENTER,true);if(combo>=2)text(c,"COMBO x"+combo,480,100,22,Color.rgb(255,201,63),Paint.Align.CENTER,true);}
  private void bar(Canvas c,float bx,float by,int v,int col,boolean rev){float w=280;fill(c,Color.rgb(40,35,31),bx,by,bx+w,by+19);float f=Math.max(0,v)/100f;if(rev)fill(c,col,bx+w-w*f+2,by+2,bx+w-2,by+17);else fill(c,col,bx+2,by+2,bx+2+(w-4)*f,by+17);stroke(c,Color.rgb(234,220,170),2,bx,by,bx+w,by+19);}
  private void fighter(Canvas c,float px,float gy,boolean enemy,int face,int attack,float timer,boolean def){int state=def?3:timer>0?2:Math.abs(enemy?evx:vx)>40?1:0;float phase=(System.currentTimeMillis()%1000)/1000f;SpriteKit.worker(c,p,px,gy,1.92f,face,state,phase,enemy);fill(c,Color.argb(75,0,0,0),px-42,gy+2,px+42,gy+10);if(timer>0){float d=face>=0?1:-1;if(attack==1)fill(c,enemy?Color.rgb(196,145,101):Color.rgb(224,174,113),px+d*18,gy-85,px+d*58,gy-68);else if(attack==2)line(c,Color.rgb(47,49,55),13,px+d*8,gy-36,px+d*64,gy-55);else if(attack==3){line(c,Color.rgb(94,194,255),13,px+d*32,gy-88,px+d*148,gy-112);line(c,Color.WHITE,3,px+d*36,gy-88,px+d*148,gy-112);}}}
  private void sync(){left=touched(bL);right=touched(bR);jump=touched(bJ);block=touched(bB);}
  @Override void onGameDown(float tx,float ty){sync();if(in(bP,tx,ty))punch=true;if(in(bK,tx,ty))kick=true;if(in(bA,tx,ty))arc=true;}
  @Override void onGameMove(float tx,float ty){sync();}@Override void onGameUp(float tx,float ty){sync();}
}
